function numberToIndianWords(num) {
  const n = Math.floor(Number(num) || 0);
  if (n <= 0) return "Zero Rupees Only";
  const a = ["", "One ", "Two ", "Three ", "Four ", "Five ", "Six ", "Seven ", "Eight ", "Nine ", "Ten ", "Eleven ", "Twelve ", "Thirteen ", "Fourteen ", "Fifteen ", "Sixteen ", "Seventeen ", "Eighteen ", "Nineteen "];
  const b = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
  const twoDigits = (x) => x < 20 ? a[x] : b[Math.floor(x / 10)] + (x % 10 ? " " + a[x % 10] : " ");
  const crore = Math.floor(n / 1e7);
  const lakh = Math.floor(n % 1e7 / 1e5);
  const thousand = Math.floor(n % 1e5 / 1e3);
  const hundred = Math.floor(n % 1e3 / 100);
  const rest = n % 100;
  let str = "";
  if (crore) str += twoDigits(crore) + "Crore ";
  if (lakh) str += twoDigits(lakh) + "Lakh ";
  if (thousand) str += twoDigits(thousand) + "Thousand ";
  if (hundred) str += a[hundred] + "Hundred ";
  if (rest) str += (str ? "and " : "") + twoDigits(rest);
  return str.trim() + " Rupees Only";
}
